import { IMMessage } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/MsgServiceInterface';
import { TeamBeInviteMode, TeamInviteMode, TeamJoinMode, TeamUpdateExtMode, TeamUpdateTeamMode } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/TeamServiceInterface';
import { IBaseSendFileOptions, ISendCustomMsgOptions, ISendTextMsgOptions } from 'nim-web-sdk-ng/dist/NIM_BROWSER_SDK/types';
export interface LocalOptions {
    /**
     添加好友模式，默认需要验证
     */
    addFriendNeedVerify: boolean;
    /**
     群组邀请模式，默认管理员可邀请
     */
    teamInviteMode: TeamInviteMode;
    /**
     群组加入模式，默认无需验证
     */
    teamJoinMode: TeamJoinMode;
    /**
     群组被邀请模式，默认需要验证
     */
    teamBeInviteMode: TeamBeInviteMode;
    /**
     群组更新模式，默认管理员可修改
     */
    teamUpdateTeamMode: TeamUpdateTeamMode;
    /**
     群组更新自定义字段模式，默认管理员可修改
     */
    teamUpdateExtMode: TeamUpdateExtMode;
    /**
     是否需要@消息提醒，默认true
     */
    needMention: boolean;
    /**
     转让群主的同时是否退出群聊，默认false
     */
    leaveOnTransfer: boolean;
    /**
     是否允许群主转让，默认false
     */
    allowTransferTeamOwner: boolean;
    /**
     是否显示在线离线状态，默认 true
     */
    loginStateVisible: boolean;
    /**
     * 发送消息前的钩子函数，异步函数
     * @param options 消息的发送参数
     * @returns Promise 处理后的发送参数
     */
    /**
      是否需要显示 p2p 消息、p2p会话列表消息已读未读，默认 false
      */
    p2pMsgReceiptVisible?: boolean;
    /**
      是否需要显示群组消息已读未读，默认 false
    */
    teamMsgReceiptVisible?: boolean;
    /**
      是否需要显示群管理员相关主动功能，默认 false
    */
    teamManagerVisible?: boolean;
    /**
      收到创建群组事件的时候，是否需要选中该会话，默认 true
    */
    teamCreatedSelect?: boolean;
    /**
      单个群管理员默认数量限制，默认 10 个
    */
    teamManagerLimit?: number;
    sendMsgBefore: <T = ISendCustomMsgOptions | IBaseSendFileOptions | ISendTextMsgOptions>(options: T, type: IMMessage['type']) => Promise<T>;
}
export type ContactType = 'blackList' | 'groupList' | 'friendList' | 'msgList';
export type Relation = 'friend' | 'stranger' | 'myself';
